//! Copies the languages-of-content table generated by Nix into `OUT_DIR`.
//!
//! The languages are declared in `assets/tongues.nix` and generated by
//! `nix/scripts/gen-tongues.py` (`nix/tongues.nix`), which is also what
//! refuses a row that could not work — a code twice, a language neither
//! subtitle service searches in. This build script does NOT generate them:
//! generating here would reimplement Nix logic (invariant 5) and would lose
//! the refusals. Same shape as `ronoctua-world/build.rs`.

use std::{env, fs, path::PathBuf};

fn main() {
    println!("cargo:rerun-if-env-changed=RONOCTUA_TONGUES_RS");

    let generated = env::var("RONOCTUA_TONGUES_RS").unwrap_or_else(|_| {
        panic!(
            "RONOCTUA_TONGUES_RS is not set.\n\
             \n\
             The languages a subtitle is searched in are generated by Nix out of\n\
             assets/tongues.nix. Enter the environment with `direnv allow` (or\n\
             `nix develop`), which sets the variable, or build through the flake\n\
             with `nix build`."
        )
    });

    println!("cargo:rerun-if-changed={generated}");

    let destination = PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR")).join("tongues.rs");
    // DELETE FIRST — the store file is read-only. See `ronoctua-tokens/build.rs`.
    let _ = fs::remove_file(&destination);
    fs::copy(&generated, &destination)
        .unwrap_or_else(|e| panic!("could not copy {generated} -> {destination:?}: {e}"));
}
